async ({ tests: { runTargeted }, delivery: { format }, git: { diff } }) => {
  const t: any = await runTargeted({ files: ["test/functions/workflow-wait.test.ts"], raise: false });
  const f = await format();
  const d = await diff(["--stat"]);
  return { counts: t.counts, failures: t.failures, f, d: d.stdout };
}
